package main

import "strings"

type Station struct {
	Name               string  `json:"stationName"`
	Lat                float64 `json:"lat"`
	Long               float64 `json:"long"`
	CRSCode            string  `json:"crsCode"`
	ConstituentCountry string  `json:"constituentCountry"`
	IATAAirportCode    string  `json:"iataAirportCode,omitempty"`
}

func stationName(crs string) string {
	for _, s := range stations {
		if s.CRSCode == crs {
			return s.Name
		}
	}
	return crs
}

func stationByName(name string) (string, bool) {
	lower := strings.ToLower(name)
	for _, s := range stations {
		if strings.ToLower(s.Name) == lower {
			return s.CRSCode, true
		}
	}
	return "", false
}

